import{H as e,at as t,it as n,vt as r}from"./chunks/framework.dmHZ7NHG.js";var i=JSON.parse(`{"title":"Quantum News Portal","description":"","frontmatter":{},"headers":[],"relativePath":"docs/quantum-news-portal.md","filePath":"docs/quantum-news-portal.md"}`),a={name:`docs/quantum-news-portal.md`};function o(e,i,a,o,s,c){return r(),n(`div`,null,[...i[0]||=[t(`<h1 id="quantum-news-portal" tabindex="-1">Quantum News Portal <a class="header-anchor" href="#quantum-news-portal" aria-label="Permalink to “Quantum News Portal”">​</a></h1><p>The honest news engine. Read articles on disputed topics → extract decidable facts → audit through the sealed ledger → four-category judgment.</p><h2 id="the-four-fact-categories" tabindex="-1">The Four Fact Categories <a class="header-anchor" href="#the-four-fact-categories" aria-label="Permalink to “The Four Fact Categories”">​</a></h2><p>Every fact extracted from an article falls into one of four provable categories:</p><p><strong>Provable</strong> (green) — The extracted fact matches a sealed theorem in the ledger. Full integrity, no overclaim.</p><p><strong>Open</strong> (yellow) — The fact is real (extracted consistently, addresses match across articles), but has no seal yet. A candidate for future sealing by the community.</p><p><strong>Overclaimed</strong> (red) — The article claims a fact that contradicts a sealed theorem. The anti-fraud MCP catches this and marks it. Integrity check failed.</p><p><strong>Narrative Gap</strong> (purple) — The fact is sealed and provably true, but the article&#39;s story or interpretation of it is false. The gate cannot catch narrative gaps — only the court (human judgment via coin-backed voting) can decide.</p><h2 id="how-it-works" tabindex="-1">How It Works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to “How It Works”">​</a></h2><ol><li><strong>Read</strong> articles on contested topics (politics, medicine, climate, history, economics)</li><li><strong>Extract</strong> decidable facts: dates (2026-08-14), numbers (42%, 25°C), logical claims</li><li><strong>Audit</strong> each fact through the sealed ledger via the anti-fraud MCP</li><li><strong>Judge</strong> via coin-backed voting: readers contribute coins to seal candidate facts or dispute overclaims</li></ol><h2 id="the-honest-boundary" tabindex="-1">The Honest Boundary <a class="header-anchor" href="#the-honest-boundary" aria-label="Permalink to “The Honest Boundary”">​</a></h2><p>The portal proves what the sealed ledger can certify — arithmetic, dates, numbers, logical derivations. It draws the honest line:</p><ul><li><strong>Provable</strong> ← sealed arithmetic (no argument)</li><li><strong>Open</strong> ← real but unsealed (let&#39;s vote)</li><li><strong>Overclaimed</strong> ← contradicts ledger (caught by the gate)</li><li><strong>Narrative Gap</strong> ← true statement, false story (court must decide)</li></ul><p>No recomputable system can catch narrative gaps. That is the boundary where human judgment must stand.</p><h2 id="build-the-portal" tabindex="-1">Build the Portal <a class="header-anchor" href="#build-the-portal" aria-label="Permalink to “Build the Portal”">​</a></h2><p>Extract facts, and audit them, through uuidna&#39;s own tools — no network, no external trust. Every extraction and audit is reproducible by anyone:</p><ul><li><strong>Extract + link</strong> decidable facts from an article with <code>uuidna_link_book</code> (or <code>linkBookFacts</code>): each fact is <code>sealed-match</code> (already a theorem), <code>novel</code> (verified, not yet sealed), or <code>refuted</code> (false arithmetic).</li><li><strong>Audit</strong> a claim through the court with <code>uuidna_trial</code> / <code>adjudicate</code>: VERIFIED · UNVERIFIED · REFUTED.</li><li><strong>Judge</strong> the narrative gap — a true statement wrapped in a false story — which no recomputable gate can catch; that stays with human judgment (coin-backed voting).</li></ul><p>These run locally (<code>npx @uuidna/uuidna</code>) and, once deployed, at <a href="/mcp">uuidna.com/mcp</a>.</p><h2 id="coin-backed-sealing" tabindex="-1">Coin-Backed Sealing <a class="header-anchor" href="#coin-backed-sealing" aria-label="Permalink to “Coin-Backed Sealing”">​</a></h2><p>When the portal finds an open fact, readers can vote to seal it:</p><ul><li><strong>Seal vote</strong> costs coins and means &quot;add this to the ledger&quot;</li><li><strong>Dispute vote</strong> costs coins and means &quot;this contradicts what I know&quot;</li><li><strong>Agree vote</strong> costs coins and means &quot;I confirm this fact is true&quot;</li></ul><p>The portal tallies coin-weighted votes. If seal votes exceed 2× dispute votes, the fact is ready to seal. The captain decides the final sealing.</p><h2 id="domain-portals" tabindex="-1">Domain Portals <a class="header-anchor" href="#domain-portals" aria-label="Permalink to “Domain Portals”">​</a></h2><p>The portal can focus on specific domains:</p><ul><li><strong>Politics</strong>: voting records, election dates, bill numbers, political claims</li><li><strong>Medicine</strong>: clinical trial results, dosages, mortality rates, medical claims</li><li><strong>Climate</strong>: temperature records, CO₂ levels, weather events, climate claims</li><li><strong>History</strong>: dates, names of figures, documented events, historical claims</li><li><strong>Economics</strong>: GDP, inflation rates, employment, economic indices</li></ul><p>Each domain extracts its own decidable facts and audits them through the sealed ledger.</p><h2 id="no-meaning-extraction" tabindex="-1">No Meaning Extraction <a class="header-anchor" href="#no-meaning-extraction" aria-label="Permalink to “No Meaning Extraction”">​</a></h2><p>The portal extracts <strong>structure only</strong> — dates, numbers, references. It does not extract meaning. A fact might be arithmetically true (2000 + 24 = 2024) but used to lie (a false historical narrative). The portal marks that as a narrative gap and defers to the court.</p><h2 id="the-honest-answer" tabindex="-1">The Honest Answer <a class="header-anchor" href="#the-honest-answer" aria-label="Permalink to “The Honest Answer”">​</a></h2><p>What can a recomputable system prove about news?</p><ul><li>✓ This date appears in the article</li><li>✓ This number is arithmetically correct</li><li>✓ This fact matches a sealed theorem</li><li>✓ This fact contradicts a sealed theorem</li><li>✗ This story is true</li><li>✗ This journalist is trustworthy</li><li>✗ This narrative is honest</li></ul><p>The portal handles everything in the ✓ list. The ✗ list stays with the court — judges, journalists, readers, historians. By construction, the portal is honest about what it cannot do.</p>`,32)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};